SELECT id, notice_title, notice_type, notice_content, status, create_by, create_time, update_by, update_time, remark FROM sys_notice WHERE status = '0'
AND notice_title LIKE CONCAT('%', #{title}, '%')
AND notice_type = #{type}
ORDER BY create_time ASC, id ASC
ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1) FROM sys_notice WHERE status = '0'
AND notice_title LIKE CONCAT('%', #{title}, '%')
AND notice_type = #{type}
